import unittest


def double(value):
    return value * 2


def negate(value):
    return -value


def make_table(pairs):
    table = {}
    for name, func in pairs:
        table[name] = func
    return table


def apply_all(funcs, value):
    return [func(value) for func in funcs]


def resolve(table, name):
    return table[name]


class DispatchTest(unittest.TestCase):
    def test_table_stores_function_objects(self):
        table = make_table([("double", double), ("negate", negate)])
        self.assertIs(table["double"], double)
        self.assertIs(table["negate"], negate)

    def test_later_pair_overwrites(self):
        table = make_table([("op", double), ("op", negate)])
        self.assertIs(table["op"], negate)
        self.assertEqual(table["op"](3), -3)

    def test_apply_all_uses_original_value(self):
        self.assertEqual(apply_all([double, negate], 3), [6, -3])

    def test_resolve_returns_callable_itself(self):
        table = make_table([("negate", negate)])
        func = resolve(table, "negate")
        self.assertIs(func, negate)
        self.assertEqual(func(5), -5)

    def test_resolve_unknown_name_raises(self):
        with self.assertRaises(KeyError):
            resolve({}, "missing")


if __name__ == "__main__":
    unittest.main()

