import unittest


class Accumulator:
    def __init__(self, start=0):
        self.total = start
        self.calls = 0

    def __call__(self, value):
        self.total += value
        self.calls += 1
        return self.total


class Negated:
    def __init__(self, func):
        self.func = func

    def __call__(self, value):
        return -self.func(value)


class Plain:
    pass


class CallableProtocolTest(unittest.TestCase):
    def test_instance_with_dunder_call_is_callable(self):
        self.assertTrue(callable(Accumulator()))
        self.assertFalse(callable(Plain()))

    def test_state_lives_on_the_instance(self):
        acc = Accumulator(10)
        self.assertEqual(acc(5), 15)
        self.assertEqual(acc(5), 20)
        self.assertEqual(acc.calls, 2)
        self.assertEqual(sorted(vars(acc)), ["calls", "total"])

    def test_call_forwards_to_given_function(self):
        wrapped = Negated(lambda value: value + 1)
        self.assertEqual(wrapped(4), -5)

    def test_plain_values_are_not_callable(self):
        self.assertFalse(callable(42))
        self.assertFalse(callable("text"))

    def test_function_object_has_dunder_call(self):
        def inc(value):
            return value + 1

        self.assertTrue(hasattr(inc, "__call__"))
        self.assertEqual(inc.__call__(1), 2)


if __name__ == "__main__":
    unittest.main()

