import inspect
import unittest


def connect(host, port=5432, *, timeout=30, retries):
    return (host, port, timeout, retries)


def tagged(*items, **meta):
    return (items, meta)


def signature_report(func):
    sig = inspect.signature(func)
    required = [
        parameter.name
        for parameter in sig.parameters.values()
        if parameter.default is inspect.Parameter.empty
        and parameter.kind
        in (
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        )
    ]
    return {
        "names": list(sig.parameters),
        "kinds": [parameter.kind.name for parameter in sig.parameters.values()],
        "required": required,
    }


def bind_call(func, *args, **kwargs):
    bound = inspect.signature(func).bind(*args, **kwargs)
    bound.apply_defaults()
    return dict(bound.arguments)


class SignatureTest(unittest.TestCase):
    def test_names_in_order(self):
        self.assertEqual(
            signature_report(connect)["names"],
            ["host", "port", "timeout", "retries"],
        )

    def test_kinds_in_order(self):
        self.assertEqual(
            signature_report(connect)["kinds"],
            [
                "POSITIONAL_OR_KEYWORD",
                "POSITIONAL_OR_KEYWORD",
                "KEYWORD_ONLY",
                "KEYWORD_ONLY",
            ],
        )

    def test_required_names(self):
        self.assertEqual(signature_report(connect)["required"], ["host", "retries"])

    def test_bound_values_and_defaults(self):
        self.assertEqual(
            bind_call(connect, "db", 5433, timeout=5, retries=2),
            {"host": "db", "port": 5433, "timeout": 5, "retries": 2},
        )
        self.assertEqual(
            bind_call(connect, "db", retries=1),
            {"host": "db", "port": 5432, "timeout": 30, "retries": 1},
        )

    def test_binding_failure_and_variadic_defaults(self):
        with self.assertRaises(TypeError):
            bind_call(connect, "db")
        self.assertEqual(bind_call(tagged), {"items": (), "meta": {}})


if __name__ == "__main__":
    unittest.main()

