import functools
import inspect
import unittest


def trace(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls.append((args, kwargs))
        return func(*args, **kwargs)

    wrapper.calls = []
    return wrapper


def public_signature(func, follow_wrapped=True):
    return str(inspect.signature(func, follow_wrapped=follow_wrapped))


def add(a, b=1):
    return a + b


class TraceTest(unittest.TestCase):
    def test_signature_follows_wrapped(self):
        traced = trace(add)
        self.assertEqual(public_signature(traced), "(a, b=1)")

    def test_signature_without_follow_wrapped(self):
        traced = trace(add)
        self.assertEqual(
            public_signature(traced, follow_wrapped=False),
            "(*args, **kwargs)",
        )

    def test_metadata_preserved(self):
        traced = trace(add)
        self.assertEqual(traced.__name__, "add")
        self.assertIs(traced.__wrapped__, add)

    def test_forwarding_and_call_log(self):
        traced = trace(add)
        self.assertEqual(traced(2), 3)
        self.assertEqual(traced(2, 5), 7)
        self.assertEqual(len(traced.calls), 2)
        self.assertEqual(traced.calls[0], ((2,), {}))

    def test_unwrap_returns_original(self):
        traced = trace(add)
        self.assertIs(inspect.unwrap(traced), add)


if __name__ == "__main__":
    unittest.main()

