import unittest
from collections.abc import Callable
from typing import Protocol, runtime_checkable


@runtime_checkable
class Handler(Protocol):
    def __call__(self, text: str) -> str: ...


class Bracket:
    def __call__(self, text):
        return "[" + text + "]"


def render(text):
    return "<" + text + ">"


def register(handlers, name, func):
    if not isinstance(func, Handler):
        raise TypeError("handler 必须可调用")
    handlers[name] = func
    return func


def apply_handler(func, text):
    return func(text)


class CallableProtocolTest(unittest.TestCase):
    def test_plain_function_matches_interface(self):
        self.assertTrue(isinstance(render, Handler))
        self.assertTrue(isinstance(render, Callable))

    def test_plain_values_do_not_match(self):
        self.assertFalse(isinstance(42, Handler))
        self.assertFalse(isinstance("render", Callable))

    def test_instance_with_dunder_call_matches(self):
        self.assertTrue(isinstance(Bracket(), Handler))
        self.assertTrue(isinstance(Bracket(), Callable))

    def test_register_rejects_non_callable(self):
        handlers = {}
        with self.assertRaises(TypeError):
            register(handlers, "bad", 42)
        self.assertEqual(handlers, {})
        self.assertIs(register(handlers, "ok", render), render)

    def test_apply_handler_forwards(self):
        self.assertEqual(apply_handler(render, "x"), "<x>")
        self.assertEqual(apply_handler(Bracket(), "x"), "[x]")


if __name__ == "__main__":
    unittest.main()

