import unittest


def strip(text):
    return text.strip()


def exclaim(text):
    return "<" + text + ">"


def apply_pipeline(text, steps):
    result = text
    for step in steps:
        result = step(result)
    return result


def pipe(*steps):
    return lambda text: apply_pipeline(text, steps)


def compose(*steps):
    return lambda text: apply_pipeline(text, tuple(reversed(steps)))


def add_step(steps, func):
    return tuple(steps) + (func,)


class PipelineTest(unittest.TestCase):
    def test_apply_pipeline_runs_in_order(self):
        self.assertEqual(apply_pipeline("  hi  ", [strip, exclaim]), "<hi>")

    def test_pipe_is_left_to_right(self):
        self.assertEqual(pipe(strip, exclaim)("  hi  "), "<hi>")

    def test_compose_is_right_to_left(self):
        self.assertEqual(compose(strip, exclaim)("  hi  "), "<  hi  >")
        self.assertEqual(compose(exclaim, strip)("  hi  "), "<hi>")

    def test_add_step_returns_new_sequence(self):
        steps = (strip,)
        extended = add_step(steps, exclaim)
        self.assertEqual(steps, (strip,))
        self.assertEqual(len(extended), 2)
        self.assertIs(extended[-1], exclaim)

    def test_empty_pipeline_returns_input(self):
        self.assertEqual(apply_pipeline("hi", []), "hi")
        self.assertEqual(pipe()("hi"), "hi")


if __name__ == "__main__":
    unittest.main()

