import unittest


def make_logger(prefix):
    entries = []

    def log(message):
        entries.append(f"{prefix}:{message}")
        return len(entries)

    def count():
        return len(entries)

    return log, count


class LifecycleTest(unittest.TestCase):
    def test_state_survives_after_factory_returns(self):
        log, count = make_logger("app")
        log("one")
        log("two")
        self.assertEqual(count(), 2)

    def test_first_call_after_return_works(self):
        log, _ = make_logger("app")
        self.assertEqual(log("boot"), 1)

    def test_two_calls_have_independent_state(self):
        first_log, first_count = make_logger("a")
        second_log, second_count = make_logger("b")
        first_log("x")
        self.assertEqual(first_count(), 1)
        self.assertEqual(second_count(), 0)

    def test_prefix_is_captured(self):
        log, _ = make_logger("db")
        log("slow")
        self.assertEqual(log("slow"), 2)

    def test_same_closure_keeps_growing(self):
        log, count = make_logger("tmp")
        log("kept")
        log("again")
        log("third")
        self.assertEqual(count(), 3)


