import functools
import unittest


def multiply(factor, value):
    return value * factor


def make_with_default(factors):
    return [lambda value, factor=factor: value * factor for factor in factors]


def make_with_factory(factors):
    def build(factor):
        return lambda value: value * factor
    return [build(factor) for factor in factors]


def make_with_partial(factors):
    return [functools.partial(multiply, factor) for factor in factors]


MAKERS = (make_with_default, make_with_factory, make_with_partial)


class LateBindingTest(unittest.TestCase):
    def test_each_maker_maps_each_factor(self):
        for maker in MAKERS:
            with self.subTest(maker=maker.__name__):
                multipliers = maker([1, 2, 3])
                self.assertEqual([multiply(10) for multiply in multipliers], [10, 20, 30])

    def test_call_order_does_not_matter(self):
        for maker in MAKERS:
            with self.subTest(maker=maker.__name__):
                first, second = maker([2, 4])
                self.assertEqual(second(5), 20)
                self.assertEqual(first(5), 10)

    def test_empty_and_length(self):
        for maker in MAKERS:
            with self.subTest(maker=maker.__name__):
                self.assertEqual(maker([]), [])
                self.assertEqual(len(maker([1, 2, 3, 4, 5])), 5)

    def test_longer_input_maps_correctly(self):
        for maker in MAKERS:
            with self.subTest(maker=maker.__name__):
                multipliers = maker([1, 2, 3, 4])
                self.assertEqual([multiply(1) for multiply in multipliers], [1, 2, 3, 4])

    def test_value_is_fixed_at_creation_time(self):
        for maker in MAKERS:
            with self.subTest(maker=maker.__name__):
                factors = [1, 2, 3]
                multipliers = maker(factors)
                factors[0] = 99
                self.assertEqual([multiply(10) for multiply in multipliers], [10, 20, 30])

    def test_three_strategies_capture_in_three_places(self):
        self.assertEqual(make_with_factory([7])[0].__code__.co_freevars, ("factor",))
        self.assertEqual(make_with_partial([7])[0].args, (7,))
        self.assertEqual(make_with_default([7])[0].__defaults__, (7,))


if __name__ == "__main__":
    unittest.main()

