import unittest


def make_counter(start=0):
    count = start

    def bump(step=1):
        nonlocal count
        count += step
        return count

    def reset():
        nonlocal count
        count = start
        return count

    return bump, reset


def make_quota(limit):
    used = 0

    def check(amount):
        nonlocal used
        if used + amount > limit:
            return False
        used += amount
        return True

    def used_count():
        return used

    return check, used_count


def make_retry(callable_, limit):
    attempts = 0

    def call(*args, **kwargs):
        nonlocal attempts
        for _ in range(limit):
            attempts += 1
            outcome = callable_(*args, **kwargs)
            if outcome is not None:
                return outcome
        return f"give-up after {limit}"

    def attempts_used():
        return attempts

    return call, attempts_used


def take_until(needed):
    seen = 0

    def step(value):
        nonlocal seen
        seen += 1
        if seen >= needed:
            return value.upper()
        return None

    return step


class FactoryTest(unittest.TestCase):
    def test_counter_and_reset_are_independent(self):
        bump, reset = make_counter(10)
        self.assertEqual(bump(5), 15)
        self.assertEqual(bump(), 16)
        self.assertEqual(reset(), 10)
        self.assertEqual(bump(), 11)

    def test_counter_state_is_private(self):
        first_bump, first_reset = make_counter(0)
        second_bump, second_reset = make_counter(0)
        first_bump()
        first_bump()
        self.assertEqual(first_reset(), 0)
        self.assertEqual(second_bump(), 1)

    def test_quota_rejects_over_limit_without_using_state(self):
        check, used_count = make_quota(10)
        self.assertTrue(check(4))
        self.assertFalse(check(8))
        self.assertTrue(check(6))
        self.assertEqual(used_count(), 10)

    def test_retry_returns_result_after_failures(self):
        call, attempts_used = make_retry(take_until(3), 5)
        self.assertEqual(call("job"), "JOB")
        self.assertEqual(attempts_used(), 3)

    def test_retry_gives_up_at_limit(self):
        call, attempts_used = make_retry(lambda value: None, 2)
        self.assertEqual(call("job"), "give-up after 2")
        self.assertEqual(call("job"), "give-up after 2")
        self.assertEqual(attempts_used(), 4)


if __name__ == "__main__":
    unittest.main()

import unittest
from functools import partial


def sort_records(records, key, reverse=False):
    return sorted(records, key=key, reverse=reverse)


def describe_partial(callable_):
    def describe(value):
        name = getattr(value, "__name__", None)
        return name if name is not None else value
    return {
        "name": callable_.func.__name__,
        "args": tuple(describe(value) for value in callable_.args),
