    import inspect
    from types import MappingProxyType

    REGISTRY = {}
    HANDLERS = MappingProxyType(REGISTRY)


    class RegistryError(ValueError):
        """注册表相关错误：继承 ValueError，方便调用方统一捕获。"""


    def _check_signature(name, handler):
        parameters = [
            p for p in inspect.signature(handler).parameters.values()
            if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
        ]
        if len(parameters) != 1 or parameters[0].name != "source":
            raise RegistryError(
                f"处理器 {name!r} 的签名必须是 (source)，实际是 {inspect.signature(handler)}"
            )


    def register(name):
        def decorator(handler):
            _check_signature(name, handler)
            if name in REGISTRY:
                raise RegistryError(f"重复注册的任务名：{name!r}")
            REGISTRY[name] = handler
            return handler
        return decorator


    def to_upper(source, options):
        return source.upper()


    def execute(name, source):
        try:
            handler = REGISTRY[name]
        except KeyError:
            raise KeyError(f"未知任务 {name!r}，可用：{sorted(REGISTRY)}") from None
        return handler(source)


