    print(execute("upper", "abc"))                      # ABC：调用侧补上 options，TypeError 消失

    try:
        @register("upper")
        def read_upper_again(source):
            return source.upper()
    except RegistryError as exc:
        print(type(exc).__name__, "upper" in str(exc))  # RegistryError True：重复注册被拒，原处理器保留

    try:
        @register("number")
        def read_number(source, base):
            return int(source, base)
    except RegistryError as exc:
        print(type(exc).__name__, "base" in str(exc))   # RegistryError True：签名不符在注册阶段被拒

    try:
        execute("xml", "a")
    except KeyError as exc:
        print("xml" in str(exc), "upper" in str(exc))   # True True：未知任务带可用名字

