import inspect
import unittest
from types import MappingProxyType


class RegistryError(ValueError):
    pass


def execute(handlers, name, source=None):
    try:
        handler = handlers[name]
    except KeyError:
        raise KeyError(f"未知任务 {name!r}，可用：{sorted(handlers)}") from None
    return handler(source)


def _positional_parameters(handler):
    return [
        p for p in inspect.signature(handler).parameters.values()
        if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
    ]


def register_handler(name, handler, table):
    if name in table:
        raise RegistryError(f"重复注册：{name!r}")
    parameters = _positional_parameters(handler)
    if len(parameters) != 1 or parameters[0].name != "source":
        raise RegistryError(
            f"处理器 {name!r} 的签名必须是 (source)，实际是 {inspect.signature(handler)}"
        )
    table[name] = handler
    return handler


def make_registry():
    table = {}
    handlers = MappingProxyType(table)

