import unittest
from types import MappingProxyType


class DuplicateHandler(ValueError):
    pass


def make_registry():
    table = {}
    handlers = MappingProxyType(table)

    def register(name):
        def decorator(handler):
            if name in table:
                raise DuplicateHandler(f"重复注册：{name}")
            table[name] = handler
            return handler
        return decorator

    return register, handlers


def count_lines(source):
    return len(source.splitlines())


def count_words(source):
    return len(source.split())


def execute(handlers, name, source=None):
    try:
        handler = handlers[name]
    except KeyError:
        raise KeyError(f"未知任务 {name!r}，可用：{sorted(handlers)}") from None
    return handler(source)


class RegistryTest(unittest.TestCase):
    def setUp(self):
        self.register, self.handlers = make_registry()

    def test_first_run_registers(self):
        @self.register("lines")
        def handler(source):
            return count_lines(source)

        self.assertEqual(execute(self.handlers, "lines", "a\nb"), 2)

    def test_fresh_registry_per_test(self):
        @self.register("lines")
        def handler(source):
            return count_lines(source)

        self.assertEqual(sorted(self.handlers), ["lines"])

    def test_core_handlers_standalone(self):
        self.assertEqual(count_lines("a\nb\nc"), 3)
        self.assertEqual(count_words("a b c"), 3)

    def test_duplicate_name_raises(self):
        @self.register("lines")
        def handler(source):
            return 1

        with self.assertRaises(DuplicateHandler):
            @self.register("lines")
            def again(source):
                return 2

        self.assertIs(self.handlers["lines"], handler)

    def test_unknown_task_raises_keyerror(self):
        @self.register("lines")
        def handler(source):
            return 1

        with self.assertRaises(KeyError) as ctx:
            execute(self.handlers, "nope")
        self.assertIn("lines", str(ctx.exception))

    def test_view_is_read_only(self):
        with self.assertRaises(TypeError):
            self.handlers["lines"] = lambda source: 0

    def test_no_module_level_state(self):
        self.assertEqual(dict(self.handlers), {})


if __name__ == "__main__":
    unittest.main()

