import unittest
from functools import singledispatch, singledispatchmethod


@singledispatch
def render(value):
    return f"default:{type(value).__name__}"


@render.register
def _(value: bool):
    return "bool"


@render.register
def _(value: int):
    return "int"


@render.register
def _(value: list):
    return "list"


@render.register
def _(value: dict):
    return "dict"


def manual_render(value):
    if isinstance(value, (int, float)):
        return "number"
    return "other"


class Row(list):
    pass


class Holder:
    @singledispatchmethod
    def render(self, value):
        return f"default:{type(value).__name__}"

    @render.register
    def _(self, value: int):
        return "int"


class RenderTest(unittest.TestCase):
    def test_int_dispatch(self):
        self.assertEqual(render(3), "int")

    def test_bool_registration_wins(self):
        self.assertEqual(render(True), "bool")

    def test_dispatch_returns_handler(self):
        self.assertEqual(render.dispatch(int)(5), "int")
        self.assertEqual(render.dispatch(bool)(True), "bool")

    def test_mro_picks_most_specific(self):
        class Tiny(int):
            pass

        self.assertEqual(render(Tiny(9)), "int")

    def test_default_fallback(self):
        self.assertEqual(render("x"), "default:str")
        self.assertEqual(render(3.5), "default:float")

    def test_new_registration(self):
        class Rows(list):
            pass

        @render.register
        def _(value: Rows):
            return "rows"

        self.addCleanup(render.register(list), render.registry[list])
        self.assertEqual(render(Rows([])), "rows")
        self.assertEqual(render([]), "list")

    def test_singledispatchmethod(self):
        holder = Holder()
        self.assertEqual(holder.render(1), "int")
        self.assertEqual(holder.render("x"), "default:str")

    def test_manual_version_is_coarse(self):
        self.assertEqual(manual_render(3), "number")
        self.assertEqual(manual_render("x"), "other")
        self.assertEqual(manual_render(True), "number")


