import unittest


def add_describe(cls):
    def describe(self):
        return f"{cls.__name__}:{self.name}"

    cls.describe = describe
    return cls


@add_describe
class User:
    def __init__(self, name):
        self.name = name


class Item:
    def __init__(self, name):
        self.name = name


class ClassDecoratorTest(unittest.TestCase):
    def setUp(self):
        if "describe" in vars(Item):
            del Item.describe
        self.decorated = add_describe(Item)

    def test_returns_same_class_object(self):
        self.assertIs(self.decorated, Item)

    def test_describe_output(self):
        self.assertEqual(Item("book").describe(), "Item:book")

    def test_old_reference_is_still_the_same_class(self):
        Legacy = Item
        self.assertIs(Legacy, self.decorated)
        self.assertTrue(isinstance(Legacy("pen"), Item))

    def test_type_identity_holds(self):
        Legacy = Item
        self.assertIs(type(Legacy("pen")), Item)

    def test_attribute_lives_on_the_class(self):
        self.assertIn("describe", vars(Item))
        self.assertNotIn("describe", vars(Item("mug")))

    def test_decorated_class_still_constructs_normally(self):
        self.assertEqual(User("gin").describe(), "User:gin")
        self.assertEqual(User("gin").name, "gin")


if __name__ == "__main__":
    unittest.main()
